            ck = candidate_key(b.candidate)
            if fk is not None and b.id not in m.block_map:
                ck = find_candidate(fcs[fk], ck, {c for f, c in used if f == fk})
                if ck is not None and (fk, ck) not in used:
                    m.block_map[b.id] = (fk, ck)
                    used.add((fk, ck))
